import { randomBytes } from 'node:crypto';

/**
 * Identity of every stored entity (user, source, playlist, notification …): a UUID.
 *
 * Generated by the application (not by the database), so an id is known before the row is
 * written and no persistence adapter owns the format. UUIDv7 (RFC 9562) puts a millisecond
 * timestamp in the high bits: new rows land at the right edge of the B-tree index instead of
 * at random pages, which keeps inserts fast as tables grow.
 */
const ENTITY_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isEntityId(value: string): boolean {
  return ENTITY_ID.test(value);
}

export function newEntityId(nowMs: number = Date.now()): string {
  const bytes = randomBytes(16);
  bytes.writeUIntBE(nowMs, 0, 6);
  bytes[6] = (bytes[6]! & 0x0f) | 0x70; // version 7
  bytes[8] = (bytes[8]! & 0x3f) | 0x80; // RFC 4122 variant
  const hex = bytes.toString('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
